INSERT dbo.departments(department_code,department_name) VALUES('HCNS',N'Hành chính nhân sự'),('DT',N'Đào tạo'),('TV',N'Tư vấn tuyển sinh'),('KT',N'Kế toán'),('CNTT',N'Công nghệ thông tin');
